test("dated settings scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "1.50");
  await ui.setSetting(pg_uma, "terms", "7");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-05");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "5.00", "from": "2026-03-16"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C"}));
  const c_dot_0 = ui.must(await ui.quickAdd(pg_uma, {"name": "Dot", "amount": "25.00"}));
  const p_dot = await ui.personId(pg_uma, "Dot");
  expect(await ui.claimAction(pg_uma, c_dot_0, "open")).toBe(true);
  expect(await ui.claimAction(pg_uma, c_dot_0, "void")).toBe(true);
  expect(await ui.hold(pg_uma, p_cam, {"from": "2026-02-10", "to": "2026-03-01"})).toBe(true);
  await ui.setToday(pg_uma, "2026-03-19");
  expect(await ui.statement(pg_uma, p_ben)).toBe(true);
  const c_dot_1 = ui.must(await ui.addClaim(pg_uma, p_dot, {"amount": "10.35", "date": "2026-03-09"}));
  await ui.refresh(pg_uma);
  expect(await ui.editPerson(pg_uma, p_cam, {"grade": "A", "gradeFrom": "2026-03-15"})).toBe(true);
  expect(await ui.hold(pg_uma, p_dot, {"from": "2026-02-25"})).toBe(true);
  const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "12.50", "date": "2026-03-15"}));
  await ui.setToday(pg_uma, "2026-04-13");
  expect(await ui.statement(pg_uma, p_dot)).toBe(true);
  const c_ben_1 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "3.33", "date": "2026-04-02"}));
  expect(await ui.periodAction(pg_uma, "P1", "close")).toBe(true);
  await ui.refresh(pg_uma);
  const c_dot_2 = ui.must(await ui.addClaim(pg_uma, p_dot, {"amount": "0.04", "date": "2026-04-02"}));
  const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "4.00", "date": "2026-02-10"}));
  const c_dot_3 = ui.must(await ui.addClaim(pg_uma, p_dot, {"amount": "20.00", "date": "2026-04-02"}));
  await ui.refresh(pg_uma);
  await ui.expectAudit(sheet, [
  ]);
});
