test("dated settings scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-04-05");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "terms", "30");
  await ui.setSetting(pg_uma, "cap", "2.00");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A"}));
  expect(await ui.exportCsv(pg_uma)).toBe("name,grade,retired-from,due-total\nCam,A,,0.00\nBen,A,,0.00\n");
  expect(await ui.statement(pg_uma, p_ben)).toBe(true);
  const c_cam_0 = ui.must(await ui.quickAdd(pg_uma, {"name": "Cam", "amount": "25.00"}, p_cam));
  expect(await ui.claimAction(pg_uma, c_cam_0, "open")).toBe(true);
  const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "1.00", "date": "2026-03-09"}));
  await ui.setToday(pg_uma, "2026-04-16");
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.claimAction(pg_wes, c_cam_0, "settle")).toBe(true);
  await ui.refresh(pg_wes);
  await expect(pg_wes.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("25.00");
  await expect(pg_wes.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("2.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-due")).toHaveText("2.50");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-status")).toHaveText("SETTLED");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_wes.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_wes.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_wes.getByTestId("rollup-claimed-total")).toHaveText("25.00");
  await expect(pg_wes.getByTestId("rollup-due-total")).toHaveText("2.00");
  await expect(pg_wes.getByTestId("rollup-overdue-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("rollup-overdue-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("header-people-count")).toHaveText("2");
  await expect(pg_wes.getByTestId("header-claims-DRAFT-count")).toHaveText("1");
  await expect(pg_wes.getByTestId("header-claims-OPEN-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("header-claims-PENDING-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("header-claims-SETTLED-count")).toHaveText("1");
  await expect(pg_wes.getByTestId("header-claims-VOID-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("header-due-total")).toHaveText("2.00");
  await expect(pg_wes.getByTestId("header-overdue-total")).toHaveText("0.00");
  const c_cam_1 = ui.must(await ui.addClaim(pg_wes, p_cam, {"amount": "3.33"}));
  await ui.refresh(pg_uma);
  expect(await ui.claimAction(pg_uma, c_ben_0, "open")).toBe(true);
  const c_cam_2 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "7.77"}));
  const c_ben_1 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "12.50", "date": "2026-02-25"}));
  expect(await ui.bulkOpen(pg_uma, [c_cam_2, c_ben_1, c_cam_1])).toEqual({ opened: 3, refused: 0 });
  expect(await ui.claimAction(pg_uma, c_cam_1, "void")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50"})).toBe(true);
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("32.77");
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("2.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_2).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_2).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_2).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-status")).toHaveText("VOID");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-due")).toHaveText("2.50");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-status")).toHaveText("SETTLED");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("13.50");
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("2.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_ben_1).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_ben_1).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_uma.getByTestId("claim-row-" + c_ben_1).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_uma.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("rollup-claimed-total")).toHaveText("46.27");
  await expect(pg_uma.getByTestId("rollup-due-total")).toHaveText("4.00");
  await expect(pg_uma.getByTestId("rollup-overdue-count")).toHaveText("2");
  await expect(pg_uma.getByTestId("rollup-overdue-total")).toHaveText("2.00");
  await expect(pg_uma.getByTestId("header-people-count")).toHaveText("2");
  await expect(pg_uma.getByTestId("header-claims-DRAFT-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-OPEN-count")).toHaveText("3");
  await expect(pg_uma.getByTestId("header-claims-PENDING-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-SETTLED-count")).toHaveText("1");
  await expect(pg_uma.getByTestId("header-claims-VOID-count")).toHaveText("1");
  await expect(pg_uma.getByTestId("header-due-total")).toHaveText("4.00");
  await expect(pg_uma.getByTestId("header-overdue-total")).toHaveText("2.00");
  await ui.setToday(pg_uma, "2026-05-07");
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.bulkSettle(pg_vic, [c_ben_1, c_cam_2, c_ben_0])).toEqual({ settled: 3, refused: 0 });
  const c_cam_3 = ui.must(await ui.addClaim(pg_vic, p_cam, {"amount": "20.00"}));
  await ui.refresh(pg_vic);
  await expect(pg_vic.getByTestId("person-row-" + p_cam).getByTestId("person-name")).toHaveText("Cam");
  await expect(pg_vic.getByTestId("person-row-" + p_cam).getByTestId("person-grade")).toHaveText("A");
  await expect(pg_vic.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("32.77");
  await expect(pg_vic.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("2.00");
  await expect(pg_vic.getByTestId("person-row-" + p_cam).getByTestId("person-statement-count")).toHaveText("0");
  await expect(pg_vic.getByTestId("person-row-" + p_cam).getByTestId("person-stated-total")).toHaveText("");
  await expect(pg_vic.getByTestId("person-row-" + p_cam).getByTestId("person-statement-date")).toHaveText("");
  await expect(pg_vic.getByTestId("person-row-" + p_cam).getByTestId("person-retired")).toHaveText("no");
